import { useEffect, useState } from 'react'
import { formatarData } from '../../regras/datas.js'

const EVENTOS = [
  ['tela', 'Telas abertas'], ['concluiu', 'Ações concluídas'], ['copiou_texto', 'Textos copiados'], ['aula', 'Aulas abertas'],
  ['checkin', 'Check-ins'], ['conquista', 'Conquistas'], ['card', 'Card'], ['gerador', 'Gerador'], ['lembrete', 'Lembrete'],
  ['comunidade', 'Comunidade'], ['oportunidade', 'Oportunidades'], ['rejeitou', 'Não se aplica'],
]

/**
 * Uso do LOMBADA: o que os autores fazem de verdade (eventos gravados pelo app).
 * Responde "quem abriu, quanto ficou, onde clicou e onde travou".
 */
export default function AdminUso({ uso, autores = [] }) {
  const [dias, setDias] = useState(28)
  const [dados, setDados] = useState(null)
  const [erro, setErro] = useState('')
  useEffect(() => {
    if (!uso) return
    let vivo = true
    setDados(null); setErro('')
    uso.carregar(dias).then((d) => vivo && setDados(d)).catch((e) => vivo && setErro(e.message))
    return () => { vivo = false }
  }, [dias, uso])

  if (!uso) return <p className="text-[14px] text-apoio">A medição de uso só existe na nuvem. Abra o Admin publicado.</p>
  const nome = (id) => autores.find((a) => a.id === id)?.nome || id
  const totais = dados?.totais || {}
  const lista = dados?.autores || []
  const travados = lista.filter((a) => (a.eventos?.tela || 0) > 0 && !(a.eventos?.concluiu > 0))

  return (
    <div className="grid gap-6">
      <div className="flex flex-wrap items-center gap-2">
        {[7, 28, 90].map((d) => (
          <button key={d} onClick={() => setDias(d)} className={'px-3 py-1.5 text-[12.5px] font-extrabold border-2 border-tinta ' + (dias === d ? 'bg-tinta text-white' : 'bg-white text-tinta hover:bg-areia')}>{d} dias</button>
        ))}
        <span className="text-[12px] text-mudo ml-2">Só autores logados. Cada pulso = 1 minuto com a aba aberta.</span>
      </div>
      {erro && <p className="text-[13px] font-bold text-alerta">{erro}</p>}
      {!dados && !erro && <p className="text-[13px] text-mudo">Carregando…</p>}
      {dados && (
        <>
          <section className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
            <Tile n={lista.length} rotulo="autores ativos" />
            <Tile n={lista.reduce((s, a) => s + (a.sessoes || 0), 0)} rotulo="sessões" />
            <Tile n={lista.reduce((s, a) => s + (a.minutos || 0), 0)} rotulo="minutos" />
            <Tile n={totais.concluiu || 0} rotulo="ações concluídas" />
            <Tile n={totais.copiou_texto || 0} rotulo="textos copiados" />
            <Tile n={totais.aula || 0} rotulo="aulas abertas" />
          </section>

          <section className="bg-areia p-5 corte-d">
            <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">Por autor</p>
            {lista.length === 0 ? <p className="text-[13.5px] text-apoio mt-2">Nenhum evento no período. Os eventos começam a aparecer assim que um autor logado abrir o LOMBADA.</p> : (
              <div className="overflow-x-auto mt-3">
                <table className="w-full text-[13px]">
                  <thead><tr className="text-left text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo border-b-2 border-tinta">
                    <th className="py-2 pr-3">Autor</th><th className="py-2 pr-3">Último</th><th className="py-2 pr-3">Sessões</th><th className="py-2 pr-3">Dias</th><th className="py-2 pr-3">Min</th>
                    <th className="py-2 pr-3">Concluiu</th><th className="py-2 pr-3">Textos</th><th className="py-2 pr-3">Aulas</th><th className="py-2 pr-3">Check-in</th><th className="py-2 pr-3">Card</th><th className="py-2 pr-3">Celular</th>
                  </tr></thead>
                  <tbody>{lista.map((a) => (
                    <tr key={a.autorId} className="border-b border-fio">
                      <td className="py-2 pr-3 font-bold">{nome(a.autorId)}</td>
                      <td className="py-2 pr-3">{formatarData(a.ultimo)}</td>
                      <td className="py-2 pr-3 tabular-nums">{a.sessoes}</td>
                      <td className="py-2 pr-3 tabular-nums">{a.diasAtivos}</td>
                      <td className="py-2 pr-3 tabular-nums">{a.minutos}</td>
                      <td className="py-2 pr-3 tabular-nums font-bold">{a.eventos?.concluiu || 0}</td>
                      <td className="py-2 pr-3 tabular-nums">{a.eventos?.copiou_texto || 0}</td>
                      <td className="py-2 pr-3 tabular-nums">{a.eventos?.aula || 0}</td>
                      <td className="py-2 pr-3 tabular-nums">{a.eventos?.checkin || 0}</td>
                      <td className="py-2 pr-3 tabular-nums">{a.eventos?.card || 0}</td>
                      <td className="py-2 pr-3 text-mudo">{Object.entries(a.telas || {}).sort((x, y) => y[1] - x[1]).slice(0, 3).map(([t, n]) => `${t} ${n}`).join(' · ')}</td>
                    </tr>
                  ))}</tbody>
                </table>
              </div>
            )}
          </section>

          <div className="grid md:grid-cols-2 gap-6">
            <section className="bg-areia p-5 corte-d">
              <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">Onde travou</p>
              <p className="text-[13.5px] text-apoio mt-1">Abriu o LOMBADA no período e não concluiu nenhuma ação.</p>
              {travados.length === 0 ? <p className="text-[13px] mt-3 font-bold">Ninguém travado.</p> : (
                <ul className="mt-3 grid gap-1.5 text-[13px]">{travados.map((a) => <li key={a.autorId}><b>{nome(a.autorId)}</b> · {a.sessoes} sessões · {a.minutos} min · textos {a.eventos?.copiou_texto || 0} · aulas {a.eventos?.aula || 0}</li>)}</ul>
              )}
            </section>
            <section className="bg-areia p-5 corte-d">
              <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">Eventos no período</p>
              <ul className="mt-3 grid grid-cols-2 gap-x-6 gap-y-1.5 text-[13px]">
                {EVENTOS.map(([k, r]) => <li key={k} className="flex justify-between border-b border-fio py-1"><span>{r}</span><b className="tabular-nums">{totais[k] || 0}</b></li>)}
                <li className="flex justify-between border-b border-fio py-1"><span>Entradas pelo e-mail</span><b className="tabular-nums">{lista.reduce((s, a) => s + 0, 0) || (totais.entrou || 0)}</b></li>
              </ul>
            </section>
          </div>
        </>
      )}
    </div>
  )
}

function Tile({ n, rotulo }) {
  return <div className="bg-tinta text-white px-4 py-4"><p className="display text-[28px] leading-none">{n}</p><p className="text-[11px] font-extrabold uppercase tracking-[.12em] text-white/60 mt-1">{rotulo}</p></div>
}
