import { useState } from 'react'
import { GENEROS } from '../../dados/exemplo.js'
import { VARIAVEIS, preencherModelo } from '../../regras/variaveis.js'
import { classeInput, Campo, Escolha, Select } from '../../componentes/campos.jsx'
import { Lista, Formulario, novoId } from './ListaEditavel.jsx'

const TIPOS = [{ valor: 'post', rotulo: 'Post de rede social' }, { valor: 'email', rotulo: 'E-mail' }, { valor: 'mensagem', rotulo: 'Mensagem direta' }]

function modeloVazio() {
  return { id: novoId('modelo'), tipo: 'post', nome: '', angulo: 'Mais pessoal', assunto: '', texto: '', genero: '', variaDe: '' }
}

export default function AdminModelos({ modelos, autores, onSalvar, onExcluir }) {
  const [edicao, setEdicao] = useState(null)
  const [autorPreview, setAutorPreview] = useState(autores[0]?.id)

  const bases = modelos.filter((m) => !m.variaDe)
  const variantesDe = (id) => modelos.filter((m) => m.variaDe === id)
  const set = (campo, valor) => setEdicao((e) => ({ ...e, [campo]: valor }))
  const existente = edicao && modelos.some((m) => m.id === edicao.id)
  const autor = autores.find((a) => a.id === autorPreview) || autores[0]
  const preview = edicao && autor ? preencherModelo(edicao.texto, autor) : null

  // Lista: bases com suas variantes logo abaixo
  const ordenados = bases.flatMap((b) => [b, ...variantesDe(b.id)])

  return (
    <div className="grid grid-cols-1 lg:grid-cols-[1fr_1.3fr] gap-8">
      <div>
        <Lista
          itens={ordenados}
          chave={(m) => m.id}
          selecionadoId={edicao?.id}
          onSelecionar={(id) => setEdicao({ genero: '', variaDe: '', assunto: '', ...modelos.find((m) => m.id === id) })}
          cabecalho={`${bases.length} modelos, ${modelos.length - bases.length} variantes por gênero`}
          rotuloNovo="Novo modelo"
          onNovo={() => setEdicao(modeloVazio())}
          renderLinha={(m) => (
            <div className={'flex items-baseline gap-3 ' + (m.variaDe ? 'pl-6' : '')}>
              <span className="text-xs uppercase tracking-wide text-mudo w-10 shrink-0">{m.tipo}</span>
              <span className="flex-1 text-tinta">{m.variaDe ? `↳ versão para ${m.genero}` : m.nome}</span>
              <span className="text-mudo shrink-0">{m.angulo}</span>
            </div>
          )}
        />
        <div className="mt-6 text-xs text-mudo leading-relaxed">
          <p className="font-medium text-apoio mb-1">Variáveis disponíveis</p>
          <p>{Object.entries(VARIAVEIS).map(([k, v]) => `{${k}} ${v.descricao.toLowerCase()}`).join(' · ')}</p>
        </div>
      </div>

      {edicao ? (
        <Formulario
          titulo={existente ? 'Editar modelo' : 'Novo modelo'}
          podeSalvar={Boolean(edicao.nome.trim() && edicao.texto.trim()) && (!edicao.variaDe || Boolean(edicao.genero))}
          onSalvar={() => {
            const limpo = { ...edicao }
            if (!limpo.variaDe) { delete limpo.variaDe; delete limpo.genero } else if (!limpo.genero) delete limpo.genero
            if (limpo.tipo !== 'email' || !limpo.assunto) delete limpo.assunto
            onSalvar(limpo); setEdicao(null)
          }}
          onCancelar={() => setEdicao(null)}
          onExcluir={existente ? () => {
            const n = variantesDe(edicao.id).length
            const aviso = n ? ` Isso também exclui ${n} variante${n > 1 ? 's' : ''} por gênero.` : ''
            if (confirm(`Excluir o modelo "${edicao.nome}"?${aviso}`)) { onExcluir(edicao.id); setEdicao(null) }
          } : null}
        >
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <Campo rotulo="Tipo"><Escolha valor={edicao.tipo} onChange={(v) => set('tipo', v)} opcoes={TIPOS} /></Campo>
            <Campo rotulo="Ângulo" ajuda="Rótulo curto da opção que o autor vê">
              <input className={classeInput} value={edicao.angulo} onChange={(e) => set('angulo', e.target.value)} />
            </Campo>
          </div>
          <Campo rotulo="Nome interno">
            <input className={classeInput} value={edicao.nome} onChange={(e) => set('nome', e.target.value)} autoFocus />
          </Campo>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <Campo rotulo="É variante de" ajuda="Deixe vazio se for um modelo base">
              <Select valor={edicao.variaDe} onChange={(v) => set('variaDe', v)} vazio="Não é variante" opcoes={bases.filter((b) => b.id !== edicao.id).map((b) => ({ valor: b.id, rotulo: b.nome }))} />
            </Campo>
            {edicao.variaDe && (
              <Campo rotulo="Gênero da variante">
                <Select valor={edicao.genero} onChange={(v) => set('genero', v)} vazio="Escolha o gênero" opcoes={GENEROS} />
              </Campo>
            )}
          </div>
          {edicao.tipo === 'email' && (
            <Campo rotulo="Assunto do e-mail">
              <input className={classeInput} value={edicao.assunto} onChange={(e) => set('assunto', e.target.value)} />
            </Campo>
          )}
          <Campo rotulo="Texto" ajuda="Use as variáveis entre chaves, ex.: {titulo_livro}">
            <textarea className={classeInput + ' min-h-48 font-mono text-sm'} value={edicao.texto} onChange={(e) => set('texto', e.target.value)} />
          </Campo>

          {preview && (
            <div className="border-t border-fio pt-4">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium">Pré-visualização</span>
                <select value={autorPreview} onChange={(e) => setAutorPreview(e.target.value)} className="text-sm border border-fio  px-2 py-1 bg-white">
                  {autores.map((a) => <option key={a.id} value={a.id}>{a.nome} · {a.livro.genero}</option>)}
                </select>
              </div>
              {preview.faltando.length > 0 && (
                <p className="text-xs text-mudo mb-2">Sem dado no cadastro deste autor: {preview.faltando.map((v) => VARIAVEIS[v].descricao.toLowerCase()).join(', ')}.</p>
              )}
              <pre className="whitespace-pre-wrap font-[inherit] text-sm text-tinta bg-areia  p-4 leading-relaxed">{preview.texto || '…'}</pre>
            </div>
          )}
        </Formulario>
      ) : (
        <div className="text-sm text-mudo border-2 border-dashed border-fio p-6">
          Selecione um modelo para editar ou clique em "Novo modelo".
        </div>
      )}
    </div>
  )
}
