import { classificarFase, NOME_FASE } from '../../regras/fase.js'
import { precisaRetomar, ultimaAtividade } from '../../regras/plano.js'
import { formatarData } from '../../regras/datas.js'
import { slugify } from '../../regras/vitrine.js'
import { verificarAcesso, STATUS_ACESSO } from '../../regras/acesso.js'
import { STATUS_CADASTRO, NOME_STATUS_CADASTRO, statusCadastro, camposFaltando } from '../../regras/aprovacao.js'
import { useState } from 'react'

/** Campo que salva ao confirmar (Enter ou botão). Mostra erro do servidor embaixo. */
function CampoEditavel({ valor, onSalvar, tipo = 'text', classe = '', placeholder = '', formatar = (v) => v, largura = 'w-full' }) {
  const [v, setV] = useState(valor || '')
  const [estado, setEstado] = useState('') // '' | 'salvando' | 'ok' | mensagem de erro
  const mudou = v !== (valor || '')
  async function salvar() {
    if (!mudou) return
    setEstado('salvando')
    try { await onSalvar(v); setEstado('ok'); setTimeout(() => setEstado(''), 1500) } catch (e) { setEstado(e.message || 'erro') }
  }
  return (
    <span className="grid gap-1">
      <span className="flex items-center gap-1.5">
        <input
          type={tipo}
          value={v}
          placeholder={placeholder}
          onChange={(e) => { setV(formatar(e.target.value)); setEstado('') }}
          onKeyDown={(e) => { if (e.key === 'Enter') salvar(); if (e.key === 'Escape') setV(valor || '') }}
          className={'bg-white border-2 px-2 py-1 text-[12.5px] focus:outline-none focus:border-tinta ' + (mudou ? 'border-ambar' : 'border-fio') + ' ' + largura + ' ' + classe}
        />
        {mudou && <button onClick={salvar} className="text-[11px] font-extrabold bg-tinta text-white px-2 py-1">{estado === 'salvando' ? '…' : 'Salvar'}</button>}
      </span>
      {estado && estado !== 'salvando' && <span className={'text-[10.5px] font-bold ' + (estado === 'ok' ? 'text-verde' : 'text-alerta')}>{estado === 'ok' ? 'salvo' : estado}</span>}
    </span>
  )
}

export default function AdminAutores({ autores, leitores, onAlterarAcesso, onAlterarCadastro, onGerarCodigo, onDefinirCodigo, onAlterarEmail, onAlterarVagas, codigos = {} }) {
  const hoje = new Date()
  const ultimaAcao = (a) =>
    a.concluidas.length ? a.concluidas.reduce((m, c) => (new Date(c.data) > new Date(m) ? c.data : m), a.concluidas[0].data) : null

  const linhas = autores
    .map((a) => ({
      autor: a,
      fase: classificarFase(a.livro, hoje),
      ultimaAcao: ultimaAcao(a),
      parado: precisaRetomar(a, hoje),
      leitores: leitores.filter((l) => l.slug === slugify(a.livro.titulo)).length,
    }))
    .sort((x, y) => new Date(ultimaAtividade(y.autor)) - new Date(ultimaAtividade(x.autor)))

  const parados = linhas.filter((l) => l.parado).length
  const emAnalise = autores.filter((a) => statusCadastro(a) === STATUS_CADASTRO.EM_ANALISE).length

  function mudarCadastro(autor, status) {
    let obs = ''
    if (status === STATUS_CADASTRO.AJUSTAR) {
      obs = window.prompt('O que o autor precisa ajustar? (aparece para ele)', autor.cadastro?.observacao || '')
      if (obs === null) return
    }
    onAlterarCadastro(autor.id, status, obs)
  }

  const Rotulo = ({ children }) => <span className="block text-[10.5px] font-extrabold uppercase tracking-[.12em] text-mudo mb-1">{children}</span>
  const Numero = ({ valor, rotulo }) => (
    <span className="grid">
      <span className="display text-[22px] leading-none tabular-nums">{valor}</span>
      <span className="text-[10.5px] font-bold uppercase tracking-[.08em] text-mudo mt-1">{rotulo}</span>
    </span>
  )

  return (
    <div>
      <p className="text-sm text-apoio mb-5">
        {autores.length} autores{emAnalise ? ` · ${emAnalise} aguardando liberação` : ''}{parados ? ` · ${parados} sem atividade há 3 semanas ou mais` : ''}.
      </p>
      <ul className="grid gap-4">
        {linhas.map(({ autor, fase, ultimaAcao: ua, parado, leitores: nLeitores }) => {
          const st = statusCadastro(autor)
          const faltas = camposFaltando(autor)
          const acesso = verificarAcesso(autor, hoje)
          return (
            <li key={autor.id} className={'grid grid-cols-1 lg:grid-cols-[1.3fr_1fr_1.2fr] gap-6 px-6 py-5 bg-areia border-l-[6px] ' + (st === STATUS_CADASTRO.EM_ANALISE ? 'border-ambar' : st === STATUS_CADASTRO.AJUSTAR || !acesso.liberado ? 'border-alerta' : 'border-tinta')}>
              {/* quem */}
              <div className="grid gap-3 content-start">
                <div>
                  <p className="display text-[20px] leading-none">{autor.nome}{parado && <span className="ml-2 align-middle text-[10px] font-extrabold uppercase tracking-[.1em] bg-alerta text-white px-1.5 py-0.5">parado</span>}</p>
                  <p className="text-[12.5px] text-apoio mt-1">{autor.livro.titulo} <span className="text-mudo">· {autor.livro.genero} · {NOME_FASE[fase]}</span></p>
                </div>
                <div>
                  <Rotulo>E-mail de acesso</Rotulo>
                  {onAlterarEmail
                    ? <CampoEditavel key={autor.email} tipo="email" valor={autor.email} onSalvar={(v) => onAlterarEmail(autor.id, v)} placeholder="e-mail" />
                    : <span className="text-[13px]">{autor.email || <span className="text-mudo">sem e-mail</span>}</span>}
                </div>
                <div>
                  <Rotulo>WhatsApp</Rotulo>
                  <span className="text-[13px]">{autor.whatsapp || <span className="text-mudo">não informado</span>}</span>
                </div>
              </div>

              {/* atividade */}
              <div className="grid grid-cols-2 gap-x-4 gap-y-4 content-start">
                <Numero valor={autor.concluidas.length} rotulo="ações feitas" />
                <Numero valor={(autor.checkins || []).length} rotulo="check-ins" />
                <Numero valor={nLeitores} rotulo="leitores" />
                <span className="grid">
                  <span className="text-[13px] font-bold leading-none mt-1">{ua ? formatarData(ua) : <span className="text-mudo">nunca</span>}</span>
                  <span className="text-[10.5px] font-bold uppercase tracking-[.08em] text-mudo mt-1">última ação</span>
                </span>
              </div>

              {/* acesso */}
              <div className="grid gap-3 content-start">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Rotulo>Cadastro</Rotulo>
                    <select
                      value={st}
                      onChange={(e) => mudarCadastro(autor, e.target.value)}
                      className={'w-full text-[12.5px] font-bold px-2 py-1.5 border-2 bg-white ' + (st === STATUS_CADASTRO.APROVADO ? 'border-fio' : st === STATUS_CADASTRO.AJUSTAR ? 'border-alerta text-alerta' : 'border-ambar')}
                      title={faltas.length ? `Faltando: ${faltas.join(', ')}` : 'Cadastro completo'}
                    >
                      {Object.values(STATUS_CADASTRO).map((x) => <option key={x} value={x}>{NOME_STATUS_CADASTRO[x]}</option>)}
                    </select>
                    {faltas.length > 0 && <span className="block text-[10.5px] text-alerta mt-1">falta: {faltas.slice(0, 3).join(', ')}{faltas.length > 3 ? '…' : ''}</span>}
                  </div>
                  <div>
                    <Rotulo>Acesso ao Método The Book Business</Rotulo>
                    <select
                      value={acesso.status}
                      onChange={(e) => onAlterarAcesso(autor.id, e.target.value)}
                      className={'w-full text-[12.5px] font-bold px-2 py-1.5 border-2 bg-white ' + (acesso.liberado ? 'border-fio' : 'border-alerta text-alerta')}
                    >
                      {Object.values(STATUS_ACESSO).map((x) => <option key={x} value={x}>{x}</option>)}
                    </select>
                  </div>
                </div>
                <div>
                  <Rotulo>Livros</Rotulo>
                  <p className="text-[12.5px]"><b>{(autor.livros || [autor.livro]).filter(Boolean).length}</b> {((autor.livros || [autor.livro]).filter(Boolean).length === 1) ? 'livro' : 'livros'} · <b>{Math.max(1, Number(autor.vagasLivros) || 1)}</b> {Math.max(1, Number(autor.vagasLivros) || 1) === 1 ? 'vaga' : 'vagas'}
                    {onAlterarVagas && <> · <button onClick={() => onAlterarVagas(autor.id, 1)} className="underline underline-offset-4 font-bold hover:text-verde">+1 vaga</button>{Math.max(1, Number(autor.vagasLivros) || 1) > 1 && <> · <button onClick={() => onAlterarVagas(autor.id, -1)} className="underline underline-offset-4 text-mudo hover:text-alerta">-1</button></>}</>}
                  </p>
                  <span className="block text-[10.5px] text-mudo mt-1">Livro adicional é pago pela Hotmart; libere a vaga depois da compra.</span>
                </div>
                {onGerarCodigo && (
                  <div>
                    <Rotulo>Código de acesso</Rotulo>
                    <div className="flex flex-wrap items-center gap-3">
                      <CampoEditavel
                        key={codigos[autor.id] || 'vazio'}
                        valor={codigos[autor.id] || ''}
                        placeholder="código"
                        formatar={(v) => v.replace(/\D/g, '').slice(0, 6)}
                        classe="display text-[18px] tracking-[.25em]"
                        largura="w-[130px]"
                        onSalvar={(v) => onDefinirCodigo(autor.id, v)}
                      />
                      <button onClick={() => { if (window.confirm('Gerar um código aleatório? O atual deixa de valer.')) onGerarCodigo(autor.id) }} className="text-[11.5px] font-bold text-mudo underline underline-offset-4 hover:text-tinta">gerar aleatório</button>
                    </div>
                    {codigos[autor.id] && autor.whatsapp && (
                      <a
                        href={`https://wa.me/${String(autor.whatsapp).replace(/\D/g, '').replace(/^(?!55)/, '55')}?text=${encodeURIComponent(`Oi, ${autor.nome.split(' ')[0]}! Seu cadastro no LOMBADA foi liberado. Entre em https://alelch.github.io/lombada/ com o e-mail ${autor.email} e o código ${codigos[autor.id]}. Guarde o código: ele é seu e vale sempre. Dá para trocar no Perfil do autor.`)}`}
                        target="_blank" rel="noopener noreferrer" className="inline-block mt-2 text-[12px] font-extrabold bg-tinta text-white px-3 py-1.5 corte-btn"
                      >Enviar e-mail e código pelo WhatsApp ↗</a>
                    )}
                  </div>
                )}
              </div>
            </li>
          )
        })}
      </ul>
    </div>
  )
}
